import{_ as a,c as t,o as n,ah as i}from"./chunks/framework.BxT5r71R.js";const d=JSON.parse('{"title":"BEFIRST东京巨蛋演出的舞台制作与选曲意图","titleTemplate":"Management 2 本篇","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/Management2/PART3/6_BEFIRST东京巨蛋演出的舞台制作与选曲意图.md","filePath":"zh-cn/Management2/PART3/6_BEFIRST东京巨蛋演出的舞台制作与选曲意图.md"}'),r={name:"zh-cn/Management2/PART3/6_BEFIRST东京巨蛋演出的舞台制作与选曲意图.md"};function o(p,e,_,S,s,T){return n(),t("div",null,[...e[0]||(e[0]=[i('<p>► 2024年3月</p><h2 id="be-first东京巨蛋演出的舞台制作与选曲意图" tabindex="-1">BE:FIRST东京巨蛋演出的舞台制作与选曲意图 <a class="header-anchor" href="#be-first东京巨蛋演出的舞台制作与选曲意图" aria-label="Permalink to &quot;BE:FIRST东京巨蛋演出的舞台制作与选曲意图&quot;">​</a></h2><p>#舞台制作 #BE:FIRST #首次巨蛋演出</p><h3 id="绝不能因为过于强调情绪感染力-让人觉得-登上巨蛋就是最高成就" tabindex="-1">“绝不能因为过于强调情绪感染力，让人觉得‘登上巨蛋就是最高成就’” <a class="header-anchor" href="#绝不能因为过于强调情绪感染力-让人觉得-登上巨蛋就是最高成就" aria-label="Permalink to &quot;“绝不能因为过于强调情绪感染力，让人觉得‘登上巨蛋就是最高成就’”&quot;">​</a></h3><p><strong>BE:FIRST首次巨蛋演出《BE:FIRST LIVE in DOME 2024 “Mainstream-Masterplan”》将于2024年7月12日0时起通过Amazon Prime Video面向全球上线。巨蛋演出前，BE:FIRST刚完成覆盖9座城市、共22场的体育馆巡演。不过，相较于体育馆巡演，这场巨蛋演出的舞台制作和演出曲目，更鲜明地呈现了组合从选秀企划《THE FIRST》一路走到今天的历程——演出甚至以正式出道歌曲《Gifted.》拉开序幕。</strong></p><p>我希望今后新成为BE:FIRST粉丝，或刚开始对他们产生兴趣的人，在购买这套演出影像制品时，能够把它当作“入门篇”，从中充分了解BE:FIRST的故事。其实，一开始我们预计，现场会有不少不太了解BE:FIRST、但被家人或朋友带来的观众，也会有人抱着“既然是巨蛋演出，那就去看看吧”的想法前来。因此，我们也有意借此机会重新讲述这个故事。不过实际上，多亏大家支持，我们收到了约50万份申请，最后几乎全是热情高涨的粉丝把巨蛋坐满了（笑）。</p><p>另一方面，我们绝不能因为过度强调故事而过于感性，让人产生“能登上巨蛋真是太好了（泪）”的感觉，仿佛“巨蛋就是最高成就”。为此，情绪感染力和冲击力都不可或缺，而我一直在思考如何取得二者之间的平衡。如果看过巨蛋演出的人，想到的不是“BE:FIRST终于登上巨蛋了，真好”，而是“太震撼了”，那这场演出就算成功了。</p><p>确定体育馆巡演的演出曲目时，每位成员都提出了自己的想法。比如，他们希望把《Gifted.》和《To The First》（选秀企划的主题曲）留到巨蛋演出时再唱。决定暂时保留《Gifted.》，是SHUNTO提出的建议。LEO也说，既然无论如何都要把这首歌放在第一首，那就想像在立川时一样，重现开门登场的形式——也就是重现2021年11月3日、正式出道两天后在立川Stage Garden举行的首次单独演出《“FIRST” One Man Show -We All Gifted.-》。</p><p>我一方面也想做这种彻底走感性路线的舞台制作，另一方面又一直在寻找不过度怀旧的平衡。因此，成员们能够主动表达自己的想法，对我来说非常有帮助。</p><p>与此同时，我们还有一个名为“Masterplan”的项目。简单来说，我们想借此表达“登上东京巨蛋，从一开始就是既定的安排”，所以希望让演出倒转时间，从最初重新开始。这样一来，起点就不应该是预出道歌曲《Shining One》，而应该是《Gifted.》。这一次，我们将它重新编排为完整管弦乐版本。（该版本于东京巨蛋演出结束后的3月11日上线发行。）</p><p>其实，从《Gifted.》在正式出道前完成时起，我就已经考虑过要在这个时机推出它的管弦乐版本。正式出道并发行《Gifted.》时，大家都说这是一首“很有攻击性的出道歌曲”。抛开是否得到认可不谈，即使不是管弦乐版本，我自己也觉得我们的态度已经传达得足够充分了。因此我想，在巨蛋演出中，让比当时成长许多的他们再次演唱《Gifted.》，这首歌所传达的信息应该能比当时更加深入人心。</p><p>至于歌曲中蕴含的信息能否传达出去，和它是否真的得到广泛传播，其实是两回事，也出现过各种情况。当时我认为《Gifted.》足以带来冲击；相反，像《Milli-Billi》这样的歌曲，虽然我非常想演唱，却觉得它应该很难触达大众。然而，它通过舞蹈圈的传播，影响范围超出了我们的想象。之后，我们沿着更加偏向嘻哈的方向继续加速，一路延伸到了《Boom Boom Back》。我由此感受到，归根结底，如何与社会大众沟通才是最重要的。</p><h3 id="忍不住落泪的场景是" tabindex="-1">忍不住落泪的场景是…… <a class="header-anchor" href="#忍不住落泪的场景是" aria-label="Permalink to &quot;忍不住落泪的场景是……&quot;">​</a></h3><p><strong>在3月2日举行的首场演出中，成员们为SKY-HI准备了一段惊喜舞台。身处现场的SKY-HI发现原本计划之外的演出突然开始，一度以为出了问题，慌张不已。对他来说，除此之外还有一些场景也让他感动得几乎落泪。</strong></p><p>当然，首场演出中成员们为我准备的惊喜舞台，也有不少让我感动到落泪的时刻（笑），但真正让我忍不住哭出来的，是《Set Sail》和《Kick Start》等歌曲。本来《Set Sail》并不是一首会让人哭出来的歌（笑）。</p><p>说到底，我原本想把BE:FIRST的巨蛋演出做成什么样呢？我希望呈现出他们平时的样子：成员们在巨蛋舞台上到处奔跑，大家开心地互相打闹。也就是说，如果他们能够以一种自然的状态演出——就像选秀企划《THE FIRST》合宿期间，在山梨的宿舍里展现出的自己，只是地点从那里换成了东京巨蛋——那就会是一场真正有意义的演出。我一直认为，正是这种“真实感”，才是娱乐最需要的东西。《Set Sail》等歌曲就让我们看到了这样的他们。亲眼看到他们那副样子时，我真的非常感动。他们看起来发自内心地开心，一股强烈的怜爱之情也随之涌上心头。</p><p><strong>在上一篇文章中，SKY-HI也曾谈到，由于没有足够的时间为巨蛋演出进行彩排，许多部分都只能押在正式演出上；而其中最让他捏一把汗的，似乎是结尾。</strong></p><p>在舞台制作上，我特别在意的一点，是他们最后退场、从舞台上“消失”的方式。那部分演出当天直接正式上场，真的让人害怕。说到底，只能靠直觉。负责现场演出制作的Kensuke（BLUE FLAP QUARTET），我想也是凭直觉完成了这段演出。通常，如果想用那样的幻术效果结束演出，就必须反复彩排；但即使无法彩排，这仍然是值得放手一搏的舞台效果。所以最后能够成功，我真的松了一口气。这是整个团队倾注心意后才实现的奇迹。请大家抱着“原来这里是未经彩排、直接正式上场的啊！”这样的想法来观看吧（笑）。</p>',18)])])}const E=a(r,[["render",o]]);export{d as __pageData,E as default};
